// Generated by ppl for __PPL_WASM__ (wasm32-browser, WasmGC backend; decision 264). ES module.
//
//   import init from "./__PPL_BASE__.js"
//   const app = await init()          // runs the program
//   await app.done                     // its exit code
//
// Under Node.js, `node __PPL_BASE__.js` runs the program and exits with its exit code.

const WASM = new URL("./__PPL_WASM__", import.meta.url);
const FILE = __PPL_FILE__;
const isNode = typeof process === "object" && !!process?.versions?.node;

class Exit {
  constructor(code) {
    this.code = code;
  }
}

async function compile(source) {
  if (source instanceof WebAssembly.Module) return source;
  if (source instanceof ArrayBuffer || ArrayBuffer.isView(source)) return WebAssembly.compile(source);
  const url = new URL(source ?? WASM, import.meta.url);
  if (url.protocol === "file:") {
    const fs = await import("node:fs/promises");
    return WebAssembly.compile(await fs.readFile(url));
  }
  return WebAssembly.compileStreaming(fetch(url));
}

/** Output: buffered, written to the process's streams (Node.js) or the console. */
async function sinks(options) {
  const fs = isNode ? await import("node:fs") : null;
  const make = (fd, given) => {
    let buf = "";
    const write = (s) => {
      if (given) return given(new TextEncoder().encode(s));
      if (fs) {
        const b = Buffer.from(s);
        let off = 0;
        while (off < b.length) {
          try {
            off += fs.writeSync(fd, b, off);
          } catch (e) {
            if (e.code !== "EAGAIN") throw e;
          }
        }
      } else {
        for (const line of s.split("\n").slice(0, -1)) (fd === 2 ? console.error : console.log)(line);
      }
    };
    return {
      put(s) {
        buf += s;
        if (buf.length > 65536) this.flush();
      },
      flush() {
        if (fs || given) {
          if (buf) write(buf);
          buf = "";
        } else {
          const nl = buf.lastIndexOf("\n");
          if (nl >= 0) {
            write(buf.slice(0, nl + 1));
            buf = buf.slice(nl + 1);
          }
        }
      },
    };
  };
  return { out: make(1, options.stdout), err: make(2, options.stderr) };
}

export default async function init(options = {}) {
  const module = await compile(options.module);
  const { out, err } = await sinks(options);
  const enc = new TextEncoder();
  const dec = new TextDecoder();
  let ex;
  const str = (r) => {
    const n = ex.str_len(r);
    const b = new Uint8Array(n);
    for (let i = 0; i < n; i++) b[i] = ex.str_byte(r, i);
    return dec.decode(b);
  };
  const mk = (s) => {
    const b = enc.encode(s);
    const r = ex.str_new(b.length);
    for (let i = 0; i < b.length; i++) ex.str_put(r, i, b[i]);
    return r;
  };
  const int = (v, unsigned) => (unsigned ? BigInt.asUintN(64, v) : v).toString();
  const f32 = (x) => {
    if (!Number.isFinite(x)) return String(x);
    for (let k = 1; k <= 9; k++) {
      const s = Number(x.toPrecision(k));
      if (Math.fround(s) === x) return String(s);
    }
    return String(x);
  };
  const ppl = {
    print_str: (r) => out.put(str(r)),
    print_i64: (v, u) => out.put(int(v, u)),
    print_f64: (x) => out.put(String(x)),
    print_f32: (x) => out.put(f32(x)),
    print_char: (c) => out.put(String.fromCodePoint(c)),
    print_nl: () => out.put("\n"),
    fmt_i64: (v, u) => mk(int(v, u)),
    fmt_f64: (x) => mk(String(x)),
    fmt_f32: (x) => mk(f32(x)),
    fmt_char: (c) => mk(String.fromCodePoint(c)),
    panic(msg, line, col) {
      out.flush();
      err.put(`panic: ${str(msg)}\n` + (line ? `  at ${FILE}:${line}:${col}\n` : ""));
      err.flush();
      throw new Exit(101);
    },
    pow_f64: Math.pow,
    clock_ms: () => BigInt(Math.floor(performance.now())),
  };
  const instance = await WebAssembly.instantiate(module, { ppl });
  ex = instance.exports;
  let code = 0;
  try {
    ex.start();
  } catch (e) {
    if (!(e instanceof Exit)) {
      out.flush();
      throw e;
    }
    code = e.code;
  }
  out.flush();
  err.flush();
  return { instance, done: Promise.resolve(code) };
}

// (Real paths: the module's is resolved, `argv[1]` may go through a symlink, as macOS's
// temporary directory does.)
const isMain =
  isNode &&
  !!import.meta.filename &&
  !!process.argv[1] &&
  (await import("node:fs")).realpathSync(process.argv[1]) === import.meta.filename;
if (isMain) {
  try {
    const app = await init();
    process.exitCode = await app.done;
  } catch (e) {
    console.error(`fatal: ${e?.stack ?? e}`);
    process.exitCode = 134;
  }
}
